classdef VIStudioHelpV16_1
    % Complete bilingual help. Existing project and workspace behavior is retained.
    methods (Static)
        function [zh,en]=content()
            zh=["1. 新增專案並選擇任務。";"填寫專案名稱，選擇分類、偵測、異常、語意、實例或關鍵點任務，再指定專案資料夾。";"";...
                "2. 連結影像、標記或資料集。";"在首頁選擇資源類型，再按「連結／定位」。模型與評估報告可稍後加入。";"";...
                "3. 依步驟開啟工作區。";"使用「資料 → 標記 → 訓練 → 評估 → 檢測」或「下一步」導航，依提示補齊缺少項目。";"";...
                "4. 保存並同步工作成果。";"在工作區按上方「同步至專案」。系統會建立新的保存檔，再更新專案連結。";"";...
                "5. 回首頁查看進度。";"重新整理首頁，查看已保存的資料數量、覆核進度、模型與報告。尚未同步的變更不會自動顯示。";"";...
                "6. 重新定位缺少的檔案。";"檔案搬移後，選擇對應資源再按「連結／定位」。若專案由其他視窗修改，請重新開啟後再儲存。";"";...
                "模型與評估狀態";"連結模型檔不等於已完成訓練或推論驗證；連結報告不代表驗收通過。請使用獨立的 validation/test 資料進行評估。";"";...
                "量測與變化偵測";"獨立量測單元與影像變化偵測目前為設計評估，尚未加入這個更新版的執行功能。"];
            en=["1. Create a project and choose a task.";"Enter a project name, select classification, detection, anomaly detection, semantic segmentation, instance segmentation, or keypoints, and choose a project folder.";"";...
                "2. Link images, annotations, or a dataset.";"Select a resource type on the homepage and click Link. You can attach a model and an evaluation report later.";"";...
                "3. Open the appropriate workspace.";"Follow Data → Label → Train → Evaluate → Inspect, or use Next. The guidance identifies missing resources and recommended actions.";"";...
                "4. Save and synchronize your work.";"Click Sync at the top of the workspace. New artifact files are created and the project links are updated.";"";...
                "5. Review saved progress on the homepage.";"Refresh the homepage to see saved data counts, annotation review progress, model links, and reports. Unsynchronized changes are not displayed automatically.";"";...
                "6. Locate missing files.";"If a file has moved, select its resource type and click Link to locate it again. If another window changes the project, reopen it before saving.";"";...
                "Model and evaluation status";"Linking a model does not verify training or inference. Attaching a report does not establish acceptance. Evaluate models using independent validation/test data.";"";...
                "Measurement and change detection";"A standalone measurement module and image change detection are under design assessment. Their execution features are not included in this help update."];
        end
        function fig=show(owner)
            if nargin<1, owner=[]; end
            fig=uifigure('Name','VIStudio | 操作說明 / User Guide','Position',[130 90 1080 760]); p=VIStudioThemeV16.palette(); fig.Color=p.Canvas; root=uigridlayout(fig,[4 1],'RowHeight',{56,36,'1x',30},'Padding',[14 10 14 10]);
            brand=uigridlayout(root,[1 2],'ColumnWidth',{180,'1x'},'Padding',[8 0 8 0],'BackgroundColor',p.Navy); uiimage(brand,'ImageSource',VIStudioThemeV16.logo(),'ScaleMethod','fit'); uilabel(brand,'Text','操作說明 / User Guide · V16.1','FontSize',18,'FontColor',[1 1 1],'FontWeight','bold');
            bar=uigridlayout(root,[1 2],'ColumnWidth',{210,'1x'},'Padding',[0 0 0 0]); mode=uidropdown(bar,'Items',{'中英對照 / Bilingual','中文 / Chinese','English'},'ItemsData',{'both','zh','en'},'Value','both','ValueChangedFcn',@(~,~) switchMode()); uilabel(bar,'Text','載入資料 → 標記 → 訓練 → 評估 → 檢測 / Data → Label → Train → Evaluate → Inspect','FontSize',11,'WordWrap','on');
            body=uigridlayout(root,[1 2],'Padding',[0 0 0 0],'ColumnWidth',{'1x','1x'}); [zh,en]=VIStudioHelpV16_1.content(); chinese=uitextarea(body,'Value',zh,'Editable','off','FontName','Microsoft JhengHei','FontSize',13); english=uitextarea(body,'Value',en,'Editable','off','FontName','Segoe UI','FontSize',13); uilabel(root,'Text','V16.1 說明更新 · 模型與專案流程沿用 V16 / Help update; project and model workflows use V16','FontSize',10,'FontColor',p.Muted);
            setappdata(fig,'VIStudioHelpControls',struct('Mode',mode,'Chinese',chinese,'English',english));
            if ~isempty(owner) && isvalid(owner), setappdata(fig,'VIStudioHelpOwner',owner); end
            function switchMode()
                switch mode.Value
                    case 'both', chinese.Visible='on'; english.Visible='on'; body.ColumnWidth={'1x','1x'}; chinese.Layout.Column=1; english.Layout.Column=2;
                    case 'zh', english.Visible='off'; chinese.Visible='on'; body.ColumnWidth={'1x',0}; chinese.Layout.Column=1;
                    case 'en', chinese.Visible='off'; english.Visible='on'; body.ColumnWidth={0,'1x'}; english.Layout.Column=2;
                end
            end
        end
    end
end
